use std::env
use std::fs
use std::process

fn pad6(n: int) -> string {
    let s = "${n}"
    let mut out = ""
    let mut i = s.len()
    while i < 6 {
        out = out + " "
        i = i + 1
    }
    out + s
}

fn emit(content: string, number: bool, counter: int) -> int {
    let mut c = counter
    if content.len() == 0 {
        return c
    }
    if !number {
        print(content)
        return c
    }
    let parts: Vec<string> = content.split("\n").collect()
    let n = parts.len()
    let mut i = 0
    while i < n {
        let line = parts[i]
        let last = i == n - 1
        if last && line.len() == 0 {
            break
        }
        c = c + 1
        println("${pad6(c)}\t${line}")
        i = i + 1
    }
    c
}

fn main() {
    let args: Vec<string> = env::args().collect()
    let mut number = false
    let mut files: Vec<string> = Vec::new()
    let mut i = 1
    while i < args.len() {
        let a = args[i]
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
        i = i + 1
    }
    let mut counter = 0
    let mut status = 0
    if files.len() == 0 {
        let s = io::read_to_string().unwrap_or("")
        counter = emit(s, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(s) => {
                    counter = emit(s, number, counter)
                }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        process::exit(status)
    }
}

